-- Own AG commercial originals. Saving an offer never executes stock or finance.
CREATE TABLE service_quotes(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,organization_id uuid NOT NULL,company_id uuid NOT NULL,sales_area_id uuid NOT NULL,partner_id uuid NOT NULL,title text NOT NULL,purpose text NOT NULL DEFAULT 'SERVICE_ESTIMATE' CHECK(purpose IN('SERVICE_ESTIMATE','SALES_QUOTATION')),kind text NOT NULL CHECK(kind IN('STANDARD','FIXED_PRICE')),currency text NOT NULL,quote_date date NOT NULL,pricing_date date NOT NULL,valid_until date NOT NULL,customer_reference text NOT NULL DEFAULT '',customer_reference_date date,requested_on date,payment_term_id uuid,shipping_term_id uuid,incoterm_id uuid,incoterm_place text NOT NULL DEFAULT '',responsible_id uuid,delivery_block text,billing_block text,header_text text NOT NULL DEFAULT '',internal_text text NOT NULL DEFAULT '',
 status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','IN_REVIEW','APPROVED','REJECTED','PUBLISHED','ACCEPTED','DECLINED','CANCELLED')),version integer NOT NULL DEFAULT 1 CHECK(version>0),data_revision integer NOT NULL DEFAULT 1 CHECK(data_revision>0),approval_snapshot jsonb,approved_snapshot jsonb,approved_at timestamptz,approved_by uuid,published_attachment_id uuid,published_at timestamptz,published_by uuid,acceptance_snapshot jsonb,decided_at timestamptz,decided_by uuid,converted_order_id uuid,converted_at timestamptz,converted_by uuid,cancel_reason text,
 CHECK(valid_until>=quote_date),CHECK(delivery_block IS NULL OR length(delivery_block)>=5),CHECK(billing_block IS NULL OR length(billing_block)>=5),CHECK((status='CANCELLED')=(cancel_reason IS NOT NULL)),CHECK(cancel_reason IS NULL OR length(cancel_reason)>=15),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,converted_order_id),FOREIGN KEY(tenant_id,id) REFERENCES documents(tenant_id,id),FOREIGN KEY(tenant_id,organization_id) REFERENCES organizations(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES company_codes(tenant_id,id),FOREIGN KEY(tenant_id,sales_area_id) REFERENCES sd_sales_areas(tenant_id,id),FOREIGN KEY(tenant_id,partner_id) REFERENCES business_partners(tenant_id,id),FOREIGN KEY(tenant_id,currency) REFERENCES currencies(tenant_id,code),FOREIGN KEY(tenant_id,payment_term_id) REFERENCES sd_terms(tenant_id,id),FOREIGN KEY(tenant_id,shipping_term_id) REFERENCES sd_terms(tenant_id,id),FOREIGN KEY(tenant_id,incoterm_id) REFERENCES sd_terms(tenant_id,id),FOREIGN KEY(tenant_id,responsible_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,approved_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,published_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,decided_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,converted_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,published_attachment_id) REFERENCES document_attachments(tenant_id,id),FOREIGN KEY(tenant_id,converted_order_id) REFERENCES sales_orders(tenant_id,id)
);
CREATE TABLE service_quote_partners(
 tenant_id uuid NOT NULL,quote_id uuid NOT NULL,role text NOT NULL CHECK(role IN('SOLD_TO','SHIP_TO','BILL_TO','PAYER')),partner_id uuid NOT NULL,address_id uuid NOT NULL,contact_id uuid,override_reason text NOT NULL DEFAULT '',
 PRIMARY KEY(tenant_id,quote_id,role),FOREIGN KEY(tenant_id,quote_id) REFERENCES service_quotes(tenant_id,id),FOREIGN KEY(tenant_id,partner_id) REFERENCES business_partners(tenant_id,id),FOREIGN KEY(tenant_id,address_id) REFERENCES partner_addresses(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES partner_contacts(tenant_id,id)
);
CREATE TABLE service_quote_items(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,quote_id uuid NOT NULL,position integer NOT NULL CHECK(position>0),parent_item_id uuid,product_id uuid NOT NULL,item_category text NOT NULL CHECK(item_category IN('STANDARD','NON_BILLABLE')),customer_material text NOT NULL DEFAULT '',description text NOT NULL,quantity numeric(18,6) NOT NULL CHECK(quantity>0),unit text NOT NULL,billing_rule text NOT NULL CHECK(billing_rule IN('TIME_MATERIAL','FIXED_PRICE','NON_BILLABLE')),cost_center text NOT NULL DEFAULT '',cost_object text NOT NULL DEFAULT '',profit_center text NOT NULL DEFAULT '',project_reference text NOT NULL DEFAULT '',requested_on date,delivery_block text,billing_block text,rejection_reason text,item_text text NOT NULL DEFAULT '',product_snapshot jsonb NOT NULL,price_snapshot jsonb NOT NULL,net numeric(20,4) NOT NULL CHECK(net>=0),tax numeric(20,4) NOT NULL CHECK(tax>=0),gross numeric(20,4) NOT NULL CHECK(gross=net+tax),
 CHECK(parent_item_id IS DISTINCT FROM id),CHECK((item_category='NON_BILLABLE')=(billing_rule='NON_BILLABLE')),CHECK(rejection_reason IS NULL OR length(rejection_reason)>=5),CHECK(delivery_block IS NULL OR length(delivery_block)>=5),CHECK(billing_block IS NULL OR length(billing_block)>=5),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,quote_id,position),FOREIGN KEY(tenant_id,quote_id) REFERENCES service_quotes(tenant_id,id),FOREIGN KEY(tenant_id,parent_item_id) REFERENCES service_quote_items(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id)
);
CREATE TABLE service_quote_schedules(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,quote_id uuid NOT NULL,item_id uuid NOT NULL,position integer NOT NULL CHECK(position>0),quantity numeric(18,6) NOT NULL CHECK(quantity>0),requested_on date NOT NULL,confirmed_on date,
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,item_id,position),FOREIGN KEY(tenant_id,quote_id) REFERENCES service_quotes(tenant_id,id),FOREIGN KEY(tenant_id,item_id) REFERENCES service_quote_items(tenant_id,id)
);
CREATE TABLE service_quote_events(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,quote_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),kind text NOT NULL,actor_id uuid NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),snapshot jsonb NOT NULL,
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,quote_id,revision),FOREIGN KEY(tenant_id,quote_id) REFERENCES service_quotes(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id)
);
CREATE TABLE service_quote_decisions(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,quote_id uuid NOT NULL,item_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN('ACCEPT','DECLINE')),reason text NOT NULL,actor_id uuid NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),published_hash text NOT NULL,
 CHECK(decision<>'DECLINE' OR length(reason)>=5),UNIQUE(tenant_id,id),UNIQUE(tenant_id,quote_id,item_id),FOREIGN KEY(tenant_id,quote_id) REFERENCES service_quotes(tenant_id,id),FOREIGN KEY(tenant_id,item_id) REFERENCES service_quote_items(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id)
);
CREATE TRIGGER service_quote_event_immutable BEFORE UPDATE OR DELETE ON service_quote_events FOR EACH ROW EXECUTE FUNCTION reject_attachment_mutation();
CREATE TRIGGER service_quote_decision_immutable BEFORE UPDATE OR DELETE ON service_quote_decisions FOR EACH ROW EXECUTE FUNCTION reject_attachment_mutation();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['service_quotes','service_quote_partners','service_quote_items','service_quote_schedules','service_quote_events','service_quote_decisions'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);
END LOOP;END$$;
CREATE FUNCTION service_quote_header_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE area_company uuid;area_org uuid;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Serviceangebot bleibt erhalten; begründeter Abbruch oder Folgevorgang erforderlich';END IF;
 SELECT s.company_id,a.organization_id INTO STRICT area_company,area_org FROM sd_sales_areas a JOIN sd_org_units s ON s.tenant_id=a.tenant_id AND s.id=a.sales_org_id WHERE a.tenant_id=NEW.tenant_id AND a.id=NEW.sales_area_id;
 IF area_company<>NEW.company_id OR area_org<>NEW.organization_id OR NOT EXISTS(SELECT 1 FROM documents d JOIN business_partners p ON p.tenant_id=d.tenant_id AND p.organization_id=d.organization_id WHERE d.tenant_id=NEW.tenant_id AND d.id=NEW.id AND d.kind='QUOTATION' AND d.organization_id=NEW.organization_id AND p.id=NEW.partner_id AND 'CUSTOMER'=ANY(p.roles)) THEN RAISE EXCEPTION 'AG gehört nicht zu diesem Vertriebsbereich, Buchungskreis oder Kunden';END IF;
 IF TG_OP='INSERT' THEN IF NEW.status<>'DRAFT' OR NEW.approved_snapshot IS NOT NULL OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.published_attachment_id IS NOT NULL OR NEW.published_by IS NOT NULL OR NEW.published_at IS NOT NULL OR NEW.acceptance_snapshot IS NOT NULL OR NEW.decided_by IS NOT NULL OR NEW.decided_at IS NOT NULL OR NEW.converted_order_id IS NOT NULL OR NEW.converted_by IS NOT NULL OR NEW.converted_at IS NOT NULL THEN RAISE EXCEPTION 'AG beginnt als kommerzieller Entwurf ohne Kundenentscheidung oder Folgeauftrag';END IF;RETURN NEW;END IF;
 IF (OLD.id,OLD.tenant_id,OLD.organization_id,OLD.company_id,OLD.sales_area_id,OLD.partner_id,OLD.currency,OLD.kind,OLD.purpose,OLD.quote_date) IS DISTINCT FROM (NEW.id,NEW.tenant_id,NEW.organization_id,NEW.company_id,NEW.sales_area_id,NEW.partner_id,NEW.currency,NEW.kind,NEW.purpose,NEW.quote_date) THEN RAISE EXCEPTION 'AG-Identität bleibt unveränderlich';END IF;
 IF OLD.status IN('DECLINED','CANCELLED') THEN RAISE EXCEPTION 'Abgeschlossener AG bleibt unveränderlich';END IF;
 IF NEW.version<OLD.version OR NEW.version>OLD.version+1 OR NEW.data_revision<OLD.data_revision OR NEW.data_revision>OLD.data_revision+1 OR (NEW.data_revision<>OLD.data_revision AND NEW.version<>OLD.version+1) THEN RAISE EXCEPTION 'AG-Version darf nicht zurückgesetzt oder übersprungen werden';END IF;
 IF NEW.status<>OLD.status AND NOT ((OLD.status IN('DRAFT','REJECTED') AND NEW.status IN('DRAFT','IN_REVIEW','CANCELLED')) OR (OLD.status='IN_REVIEW' AND NEW.status IN('DRAFT','APPROVED','REJECTED')) OR (OLD.status='APPROVED' AND NEW.status IN('DRAFT','PUBLISHED')) OR (OLD.status='PUBLISHED' AND NEW.status IN('ACCEPTED','DECLINED'))) THEN RAISE EXCEPTION 'Unzulässiger AG-Statusübergang';END IF;
 IF OLD.status='IN_REVIEW' AND (to_jsonb(OLD)-'status'-'version'-'approved_snapshot'-'approved_at'-'approved_by') IS DISTINCT FROM (to_jsonb(NEW)-'status'-'version'-'approved_snapshot'-'approved_at'-'approved_by') THEN RAISE EXCEPTION 'AG-Prüfstand ist während Freigabe gebunden';END IF;
 IF OLD.status='APPROVED' AND NEW.status<>'DRAFT' AND (OLD.approval_snapshot,OLD.approved_snapshot,OLD.approved_at,OLD.approved_by) IS DISTINCT FROM (NEW.approval_snapshot,NEW.approved_snapshot,NEW.approved_at,NEW.approved_by) THEN RAISE EXCEPTION 'Genehmigter AG-Originalstand bleibt unveränderlich';END IF;
 IF OLD.status='APPROVED' AND (to_jsonb(OLD)-'status'-'version'-'approval_snapshot'-'approved_snapshot'-'approved_at'-'approved_by'-'published_attachment_id'-'published_by'-'published_at') IS DISTINCT FROM (to_jsonb(NEW)-'status'-'version'-'approval_snapshot'-'approved_snapshot'-'approved_at'-'approved_by'-'published_attachment_id'-'published_by'-'published_at') THEN RAISE EXCEPTION 'Genehmigter AG benötigt vor Änderung eine begründete Rücknahme';END IF;
 IF OLD.status='PUBLISHED' AND (to_jsonb(OLD)-'status'-'version'-'acceptance_snapshot'-'decided_by'-'decided_at') IS DISTINCT FROM (to_jsonb(NEW)-'status'-'version'-'acceptance_snapshot'-'decided_by'-'decided_at') THEN RAISE EXCEPTION 'Veröffentlichtes Angebotsoriginal bleibt unveränderlich';END IF;
 IF OLD.status='ACCEPTED' AND (OLD.converted_order_id IS NOT NULL OR (to_jsonb(OLD)-'version'-'converted_order_id'-'converted_by'-'converted_at') IS DISTINCT FROM (to_jsonb(NEW)-'version'-'converted_order_id'-'converted_by'-'converted_at')) THEN RAISE EXCEPTION 'Angenommener AG erlaubt nur eine quellengebundene Folgeübernahme';END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER service_quote_header BEFORE INSERT OR UPDATE OR DELETE ON service_quotes FOR EACH ROW EXECUTE FUNCTION service_quote_header_guard();
CREATE FUNCTION service_quote_child_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE q service_quotes;quote_key uuid;partner_row business_partners;address_row partner_addresses;product_row products;BEGIN
 quote_key:=CASE WHEN TG_OP='DELETE' THEN OLD.quote_id ELSE NEW.quote_id END;
 SELECT * INTO STRICT q FROM service_quotes WHERE tenant_id=CASE WHEN TG_OP='DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END AND id=quote_key FOR UPDATE;
 IF q.status NOT IN('DRAFT','REJECTED') THEN RAISE EXCEPTION 'AG-Partner, Positionen und Einteilungen sind an den Prüf-/Originalstand gebunden';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 IF TG_OP='UPDATE' AND (OLD.tenant_id,OLD.quote_id) IS DISTINCT FROM (NEW.tenant_id,NEW.quote_id) THEN RAISE EXCEPTION 'AG-Quellenzuordnung bleibt erhalten';END IF;
 IF TG_TABLE_NAME='service_quote_partners' THEN
  SELECT * INTO STRICT partner_row FROM business_partners WHERE tenant_id=NEW.tenant_id AND id=NEW.partner_id;
  SELECT * INTO STRICT address_row FROM partner_addresses WHERE tenant_id=NEW.tenant_id AND id=NEW.address_id;
  IF partner_row.organization_id<>q.organization_id OR NOT 'CUSTOMER'=ANY(partner_row.roles) OR address_row.partner_id<>NEW.partner_id OR NOT address_row.active OR (NEW.role='SOLD_TO' AND NEW.partner_id<>q.partner_id) OR (NEW.partner_id<>q.partner_id AND length(NEW.override_reason)<15) OR (NEW.role='SOLD_TO' AND address_row.kind<>'BUSINESS') OR (NEW.role='SHIP_TO' AND address_row.kind NOT IN('BUSINESS','SERVICE')) OR (NEW.role IN('BILL_TO','PAYER') AND address_row.kind NOT IN('BUSINESS','BILLING')) THEN RAISE EXCEPTION 'AG-Partnerrolle benötigt passenden Kunden und konkrete aktive Anschrift';END IF;
  IF NEW.contact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM partner_contacts c WHERE c.tenant_id=NEW.tenant_id AND c.id=NEW.contact_id AND c.partner_id=NEW.partner_id AND c.active AND (c.valid_from IS NULL OR c.valid_from<=q.quote_date) AND (c.valid_to IS NULL OR c.valid_to>=q.quote_date)) THEN RAISE EXCEPTION 'AG-Ansprechpartner gehört nicht zur gültigen Rollenbeziehung';END IF;
 ELSIF TG_TABLE_NAME='service_quote_items' THEN
  IF TG_OP='UPDATE' AND (OLD.id,OLD.position) IS DISTINCT FROM (NEW.id,NEW.position) THEN RAISE EXCEPTION 'AG-Positionsidentität bleibt erhalten';END IF;
  SELECT p.* INTO STRICT product_row FROM products p JOIN documents d ON d.tenant_id=p.tenant_id AND d.id=p.id WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.product_id AND d.organization_id=q.organization_id;
  IF NEW.unit<>product_row.unit OR product_row.status<>'ACTIVE' OR (product_row.kind='INTERNAL' AND NEW.item_category<>'NON_BILLABLE') OR (q.kind='FIXED_PRICE' AND NEW.billing_rule<>'FIXED_PRICE') THEN RAISE EXCEPTION 'AG-Artikel/Einheit oder reine Festpreisart ist nicht erfüllt';END IF;
  IF NEW.parent_item_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM service_quote_items i WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.parent_item_id AND i.quote_id=NEW.quote_id AND i.position<NEW.position) THEN RAISE EXCEPTION 'AG-Überposition muss eine frühere eigene Position sein';END IF;
 ELSIF TG_TABLE_NAME='service_quote_schedules' THEN
  IF NOT EXISTS(SELECT 1 FROM service_quote_items i WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.item_id AND i.quote_id=NEW.quote_id) THEN RAISE EXCEPTION 'AG-Einteilung gehört nicht zu dieser Position';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER service_quote_partner BEFORE INSERT OR UPDATE OR DELETE ON service_quote_partners FOR EACH ROW EXECUTE FUNCTION service_quote_child_guard();
CREATE TRIGGER service_quote_item BEFORE INSERT OR UPDATE OR DELETE ON service_quote_items FOR EACH ROW EXECUTE FUNCTION service_quote_child_guard();
CREATE TRIGGER service_quote_schedule BEFORE INSERT OR UPDATE OR DELETE ON service_quote_schedules FOR EACH ROW EXECUTE FUNCTION service_quote_child_guard();
CREATE FUNCTION service_quote_decision_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE q service_quotes;BEGIN
 SELECT * INTO STRICT q FROM service_quotes WHERE tenant_id=NEW.tenant_id AND id=NEW.quote_id FOR UPDATE;
 IF q.status<>'PUBLISHED' OR q.valid_until<(now() AT TIME ZONE 'Europe/Berlin')::date OR q.published_attachment_id IS NULL OR NEW.published_hash<>encode(sha256(convert_to(q.approved_snapshot::text,'UTF8')),'hex') OR NOT EXISTS(SELECT 1 FROM service_quote_items i WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.item_id AND i.quote_id=NEW.quote_id AND i.rejection_reason IS NULL) OR NOT EXISTS(SELECT 1 FROM users usr JOIN user_organizations org ON org.tenant_id=usr.tenant_id AND org.user_id=usr.id WHERE usr.tenant_id=NEW.tenant_id AND usr.id=NEW.actor_id AND usr.active AND usr.role='CUSTOMER' AND usr.partner_id=q.partner_id AND org.organization_id=q.organization_id) THEN RAISE EXCEPTION 'Angebotsentscheidung benötigt gültiges veröffentlichtes Original und eigenen tatsächlichen Kunden';END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER service_quote_decision BEFORE INSERT ON service_quote_decisions FOR EACH ROW EXECUTE FUNCTION service_quote_decision_guard();
CREATE FUNCTION service_quote_event_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE q service_quotes;BEGIN
 SELECT * INTO STRICT q FROM service_quotes WHERE tenant_id=NEW.tenant_id AND id=NEW.quote_id;
 IF q.status NOT IN('DRAFT','REJECTED') OR NEW.revision<>q.data_revision OR NOT EXISTS(SELECT 1 FROM users usr JOIN user_organizations org ON org.tenant_id=usr.tenant_id AND org.user_id=usr.id WHERE usr.tenant_id=NEW.tenant_id AND usr.id=NEW.actor_id AND usr.active AND usr.role IN('ADMIN','SERVICE_MANAGER','SALES') AND org.organization_id=q.organization_id) THEN RAISE EXCEPTION 'AG-Änderungsverlauf benötigt tatsächliche Revision und berechtigten Bearbeiter';END IF;RETURN NEW;
END$$;
CREATE TRIGGER service_quote_event_source BEFORE INSERT ON service_quote_events FOR EACH ROW EXECUTE FUNCTION service_quote_event_guard();
ALTER TABLE document_attachments DROP CONSTRAINT document_attachments_document_type_check;
ALTER TABLE document_attachments ADD CONSTRAINT document_attachments_document_type_check CHECK(document_type IN('RECORD','ORDER_CONFIRMATION','PURCHASE_ORDER','GOODS_RECEIPT','DELIVERY_NOTE','SERVICE_REPORT','EXTERNAL_PDF','INVOICE','QUOTATION'));
CREATE FUNCTION service_quote_approval_consistent() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE q service_quotes;creator uuid;snapshot jsonb;offer_number text;BEGIN
 SELECT * INTO STRICT q FROM service_quotes WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 SELECT created_by,number INTO STRICT creator,offer_number FROM documents WHERE tenant_id=q.tenant_id AND id=q.id;
 IF NOT EXISTS(SELECT 1 FROM service_quote_events e WHERE e.tenant_id=q.tenant_id AND e.quote_id=q.id AND e.revision=q.data_revision) THEN RAISE EXCEPTION 'Tatsächlicher AG-Änderungsverlauf fehlt';END IF;
 IF q.status='IN_REVIEW' AND (q.approval_snapshot IS NULL OR NOT EXISTS(SELECT 1 FROM approval_instances ai WHERE ai.tenant_id=q.tenant_id AND ai.document_id=q.id AND ai.status IN('PENDING','INFORMATION_REQUIRED') AND ai.four_eyes AND ai.subject_version=q.version)) THEN RAISE EXCEPTION 'AG-Prüfstand benötigt tatsächlichen unabhängigen Workflow';END IF;
 IF q.status NOT IN('APPROVED','PUBLISHED','ACCEPTED','DECLINED') THEN
  IF q.approved_snapshot IS NOT NULL OR q.approved_by IS NOT NULL OR q.approved_at IS NOT NULL OR q.published_attachment_id IS NOT NULL OR q.published_by IS NOT NULL OR q.published_at IS NOT NULL OR q.acceptance_snapshot IS NOT NULL OR q.decided_by IS NOT NULL OR q.decided_at IS NOT NULL OR q.converted_order_id IS NOT NULL OR q.converted_at IS NOT NULL OR q.converted_by IS NOT NULL THEN RAISE EXCEPTION 'Unvollständige Angebotsfreigabe darf keinen Original- oder Kundenentscheidungsstand vortäuschen';END IF;RETURN NULL;
 END IF;
 snapshot:=q.approval_snapshot;
 IF snapshot IS NULL OR q.approved_snapshot->'commercial' IS DISTINCT FROM snapshot OR q.approved_by IS NULL OR q.approved_at IS NULL OR q.approved_snapshot->'review'->>'actorId' IS DISTINCT FROM q.approved_by::text OR (q.approved_snapshot->'review'->>'at')::timestamptz IS DISTINCT FROM q.approved_at OR coalesce(length(q.approved_snapshot->'review'->>'note'),0)<15 THEN RAISE EXCEPTION 'Gebundener vollständiger AG-Freigabestand fehlt';END IF;
 IF q.approved_by=creator OR EXISTS(SELECT 1 FROM service_quote_events e WHERE e.tenant_id=q.tenant_id AND e.quote_id=q.id AND e.actor_id=q.approved_by) OR NOT EXISTS(SELECT 1 FROM approval_instances ai JOIN approval_decisions ad ON ad.tenant_id=ai.tenant_id AND ad.instance_id=ai.id WHERE ai.tenant_id=q.tenant_id AND ai.document_id=q.id AND ai.status='APPROVED' AND ai.four_eyes AND ai.submitted_by<>q.approved_by AND ad.actor_id=q.approved_by AND ad.decision='APPROVE' AND ad.step=jsonb_array_length(ai.steps_snapshot)-1 AND ad.comment=q.approved_snapshot->'review'->>'note' AND ad.context->>'role' IN('ADMIN','SERVICE_MANAGER','SALES','EXECUTIVE') AND ad.context->>'preparedHash'=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'AG-Freigabe benötigt tatsächliche unabhängige Entscheidung zum konkreten kommerziellen Stand';END IF;
 IF snapshot->>'id' IS DISTINCT FROM q.id::text OR snapshot->>'organizationId' IS DISTINCT FROM q.organization_id::text OR snapshot->'company'->>'id' IS DISTINCT FROM q.company_id::text OR snapshot->'area'->>'id' IS DISTINCT FROM q.sales_area_id::text OR (snapshot->>'dataRevision')::int IS DISTINCT FROM q.data_revision OR snapshot->'header'->>'partnerId' IS DISTINCT FROM q.partner_id::text OR snapshot->'header'->>'currency' IS DISTINCT FROM q.currency OR snapshot->'header'->>'purpose' IS DISTINCT FROM q.purpose OR snapshot->'header'->>'kind' IS DISTINCT FROM q.kind OR snapshot->'header'->>'title' IS DISTINCT FROM q.title OR (snapshot->'header'->>'quoteDate')::date IS DISTINCT FROM q.quote_date OR (snapshot->'header'->>'validUntil')::date IS DISTINCT FROM q.valid_until OR (snapshot->'header'->>'pricingDate')::date IS DISTINCT FROM q.pricing_date OR snapshot->'header'->>'customerReference' IS DISTINCT FROM q.customer_reference OR q.requested_on IS NULL OR q.responsible_id IS NULL OR q.payment_term_id IS NULL OR q.shipping_term_id IS NULL OR q.incoterm_id IS NULL OR q.incoterm_place='' OR q.delivery_block IS NOT NULL OR q.billing_block IS NOT NULL THEN RAISE EXCEPTION 'AG-Herkunft, Vollständigkeit oder Datenrevision stimmt nicht';END IF;
 IF (SELECT count(*) FROM service_quote_partners WHERE tenant_id=q.tenant_id AND quote_id=q.id)<>4 OR jsonb_array_length(snapshot->'partners')<>4 OR EXISTS(SELECT 1 FROM service_quote_partners r WHERE r.tenant_id=q.tenant_id AND r.quote_id=q.id AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'partners') x WHERE x->>'role'=r.role AND x->>'partnerId'=r.partner_id::text AND x->'address'->>'id'=r.address_id::text AND (x->'contact'->>'id') IS NOT DISTINCT FROM r.contact_id::text)) THEN RAISE EXCEPTION 'Vollständige gebundene AG-Partner-/Adressrollen fehlen';END IF;
 IF jsonb_array_length(snapshot->'items')<>(SELECT count(*) FROM service_quote_items WHERE tenant_id=q.tenant_id AND quote_id=q.id) OR NOT EXISTS(SELECT 1 FROM service_quote_items WHERE tenant_id=q.tenant_id AND quote_id=q.id AND rejection_reason IS NULL) OR EXISTS(SELECT 1 FROM service_quote_items item WHERE item.tenant_id=q.tenant_id AND item.quote_id=q.id AND (NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'items') x WHERE x->>'id'=item.id::text AND x->>'productId'=item.product_id::text AND x->>'description'=item.description AND (x->>'parentItemId') IS NOT DISTINCT FROM item.parent_item_id::text AND (x->>'quantity')::numeric=item.quantity AND x->>'unit'=item.unit AND x->>'billingRule'=item.billing_rule AND x->>'customerMaterial'=item.customer_material AND x->>'costCenter'=item.cost_center AND x->>'costObject'=item.cost_object AND x->>'profitCenter'=item.profit_center AND x->>'projectReference'=item.project_reference AND x->>'itemText'=item.item_text AND x->'price'=item.price_snapshot AND x->'product'=item.product_snapshot AND (x->>'net')::numeric=item.net AND (x->>'tax')::numeric=item.tax AND (x->>'gross')::numeric=item.gross AND (x->>'rejectionReason') IS NOT DISTINCT FROM item.rejection_reason) OR (item.rejection_reason IS NULL AND (item.cost_center='' OR item.cost_object='' OR item.delivery_block IS NOT NULL OR item.billing_block IS NOT NULL OR (q.kind='FIXED_PRICE' AND item.billing_rule<>'FIXED_PRICE') OR item.quantity<>(SELECT coalesce(sum(quantity),0) FROM service_quote_schedules WHERE tenant_id=item.tenant_id AND item_id=item.id))))) THEN RAISE EXCEPTION 'AG-Positionen, Preise oder Einteilungen passen nicht zum tatsächlichen Freigabestand';END IF;
 IF EXISTS((SELECT id,item_id,position,quantity,requested_on,confirmed_on FROM service_quote_schedules WHERE tenant_id=q.tenant_id AND quote_id=q.id EXCEPT ALL SELECT x.id,x."itemId",x.position,x.quantity,x."requestedOn",x."confirmedOn" FROM jsonb_to_recordset(snapshot->'schedules') AS x(id uuid,"itemId" uuid,position integer,quantity numeric,"requestedOn" date,"confirmedOn" date)) UNION ALL (SELECT x.id,x."itemId",x.position,x.quantity,x."requestedOn",x."confirmedOn" FROM jsonb_to_recordset(snapshot->'schedules') AS x(id uuid,"itemId" uuid,position integer,quantity numeric,"requestedOn" date,"confirmedOn" date) EXCEPT ALL SELECT id,item_id,position,quantity,requested_on,confirmed_on FROM service_quote_schedules WHERE tenant_id=q.tenant_id AND quote_id=q.id)) THEN RAISE EXCEPTION 'AG-Termineinteilungen stimmen nicht mit der unabhängigen Freigabe überein';END IF;
 IF q.status='APPROVED' THEN
  IF NOT EXISTS(SELECT 1 FROM users usr JOIN user_organizations org ON org.tenant_id=usr.tenant_id AND org.user_id=usr.id WHERE usr.tenant_id=q.tenant_id AND usr.id=q.approved_by AND usr.active AND usr.role IN('ADMIN','SERVICE_MANAGER','SALES','EXECUTIVE') AND org.organization_id=q.organization_id) OR NOT EXISTS(SELECT 1 FROM sd_sales_areas a JOIN sd_org_units so ON so.tenant_id=a.tenant_id AND so.id=a.sales_org_id JOIN sd_org_units ch ON ch.tenant_id=a.tenant_id AND ch.id=a.channel_id JOIN sd_org_units di ON di.tenant_id=a.tenant_id AND di.id=a.division_id WHERE a.tenant_id=q.tenant_id AND a.id=q.sales_area_id AND a.active AND so.active AND ch.active AND di.active AND a.version=(snapshot->'area'->>'version')::int AND so.version=(snapshot->'area'->>'salesOrgVersion')::int AND ch.version=(snapshot->'area'->>'channelVersion')::int AND di.version=(snapshot->'area'->>'divisionVersion')::int) THEN RAISE EXCEPTION 'Aktiver unabhängiger Freigeber oder gebundener AG-Vertriebsbereich fehlt';END IF;
  IF EXISTS(SELECT 1 FROM service_quote_partners r JOIN business_partners bp ON bp.tenant_id=r.tenant_id AND bp.id=r.partner_id JOIN partner_addresses pa ON pa.tenant_id=r.tenant_id AND pa.id=r.address_id WHERE r.tenant_id=q.tenant_id AND r.quote_id=q.id AND (bp.status<>'ACTIVE' OR NOT pa.active OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'partners') x WHERE x->>'role'=r.role AND (x->>'version')::int=bp.version AND (x->'address'->>'version')::int=pa.version))) OR EXISTS(SELECT 1 FROM service_quote_items i JOIN products p ON p.tenant_id=i.tenant_id AND p.id=i.product_id WHERE i.tenant_id=q.tenant_id AND i.quote_id=q.id AND i.rejection_reason IS NULL AND p.status<>'ACTIVE') THEN RAISE EXCEPTION 'AG-Partner, Anschrift oder Artikel ist nicht mehr freigegeben';END IF;
  IF q.published_attachment_id IS NOT NULL OR q.published_at IS NOT NULL OR q.published_by IS NOT NULL THEN RAISE EXCEPTION 'Interne Angebotsfreigabe ist noch keine Kundenbereitstellung';END IF;
 ELSE
  IF q.published_attachment_id IS NULL OR q.published_at IS NULL OR q.published_by IS NULL OR NOT EXISTS(SELECT 1 FROM document_attachments a WHERE a.tenant_id=q.tenant_id AND a.id=q.published_attachment_id AND a.source_id=q.id AND a.document_type='QUOTATION' AND a.origin='GENERATED' AND a.visibility='CUSTOMER' AND a.created_by=q.published_by AND a.source_snapshot->>'number'=offer_number AND a.source_snapshot->>'commercialHash'=encode(sha256(convert_to(q.approved_snapshot::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'Kundenbereitstellung benötigt tatsächliches archiviertes Angebotsoriginal';END IF;
 END IF;
 IF q.status IN('APPROVED','PUBLISHED') AND (q.acceptance_snapshot IS NOT NULL OR q.decided_at IS NOT NULL OR q.decided_by IS NOT NULL OR EXISTS(SELECT 1 FROM service_quote_decisions d WHERE d.tenant_id=q.tenant_id AND d.quote_id=q.id)) THEN RAISE EXCEPTION 'Noch nicht entschiedenes Angebot darf keine Kundenannahme vortäuschen';END IF;
 IF q.status IN('ACCEPTED','DECLINED') THEN
  IF q.decided_by IS NULL OR q.decided_at IS NULL OR q.acceptance_snapshot IS NULL OR q.acceptance_snapshot->>'quoteId' IS DISTINCT FROM q.id::text OR q.acceptance_snapshot->>'actorId' IS DISTINCT FROM q.decided_by::text OR (q.acceptance_snapshot->>'at')::timestamptz IS DISTINCT FROM q.decided_at OR q.acceptance_snapshot->>'publishedHash' IS DISTINCT FROM encode(sha256(convert_to(q.approved_snapshot::text,'UTF8')),'hex') OR (SELECT count(*) FROM service_quote_decisions WHERE tenant_id=q.tenant_id AND quote_id=q.id)<>(SELECT count(*) FROM service_quote_items WHERE tenant_id=q.tenant_id AND quote_id=q.id AND rejection_reason IS NULL) OR EXISTS(SELECT 1 FROM service_quote_decisions d WHERE d.tenant_id=q.tenant_id AND d.quote_id=q.id AND (d.actor_id<>q.decided_by OR d.published_hash<>q.acceptance_snapshot->>'publishedHash')) OR (q.status='ACCEPTED') IS DISTINCT FROM EXISTS(SELECT 1 FROM service_quote_decisions d WHERE d.tenant_id=q.tenant_id AND d.quote_id=q.id AND d.decision='ACCEPT') THEN RAISE EXCEPTION 'Kundenentscheidungen sind nicht vollständig an das tatsächliche Angebotsoriginal gebunden';END IF;
 END IF;
 IF q.status IN('ACCEPTED','DECLINED') THEN
  IF q.acceptance_snapshot->>'partnerId' IS DISTINCT FROM q.partner_id::text OR q.acceptance_snapshot->>'documentHash' IS DISTINCT FROM (SELECT sha256 FROM document_attachments WHERE tenant_id=q.tenant_id AND id=q.published_attachment_id) OR (q.status='ACCEPTED' AND coalesce(length(q.acceptance_snapshot->>'customerReference'),0)=0) THEN RAISE EXCEPTION 'Kundenbestellung, Identität oder tatsächlicher Dokumenthash fehlt';END IF;
  IF EXISTS((SELECT item_id,decision,reason FROM service_quote_decisions WHERE tenant_id=q.tenant_id AND quote_id=q.id EXCEPT ALL SELECT x."itemId",x.decision,x.reason FROM jsonb_to_recordset(q.acceptance_snapshot->'decisions') AS x("itemId" uuid,decision text,reason text)) UNION ALL (SELECT x."itemId",x.decision,x.reason FROM jsonb_to_recordset(q.acceptance_snapshot->'decisions') AS x("itemId" uuid,decision text,reason text) EXCEPT ALL SELECT item_id,decision,reason FROM service_quote_decisions WHERE tenant_id=q.tenant_id AND quote_id=q.id)) OR EXISTS((SELECT item_id FROM service_quote_decisions WHERE tenant_id=q.tenant_id AND quote_id=q.id AND decision='ACCEPT' EXCEPT ALL SELECT x::uuid FROM jsonb_array_elements_text(q.acceptance_snapshot->'acceptedItemIds') x) UNION ALL (SELECT x::uuid FROM jsonb_array_elements_text(q.acceptance_snapshot->'acceptedItemIds') x EXCEPT ALL SELECT item_id FROM service_quote_decisions WHERE tenant_id=q.tenant_id AND quote_id=q.id AND decision='ACCEPT')) THEN RAISE EXCEPTION 'Originalentscheidungen und gespeicherter Kundenannahmestand stimmen nicht überein';END IF;
 END IF;
 IF q.converted_order_id IS NOT NULL THEN
  IF q.status<>'ACCEPTED' OR q.converted_by IS NULL OR q.converted_at IS NULL THEN RAISE EXCEPTION 'Nur tatsächlich angenommener AG besitzt eine vollständige Folgeübernahme';END IF;
  PERFORM assert_quote_order_source(q.tenant_id,q.converted_order_id);
 ELSIF q.converted_by IS NOT NULL OR q.converted_at IS NOT NULL THEN RAISE EXCEPTION 'AG-Folgeübernahme benötigt einen tatsächlichen AU';END IF;
 RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER service_quote_approval_complete AFTER INSERT OR UPDATE ON service_quotes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION service_quote_approval_consistent();

-- AG acceptance binds exactly one independent AU. Execution may later be service
-- or direct sales; no technical ticket is required for this commercial copy.
ALTER TABLE sales_orders ADD COLUMN source_quote_id uuid,ADD FOREIGN KEY(tenant_id,source_quote_id) REFERENCES service_quotes(tenant_id,id),ADD UNIQUE(tenant_id,source_quote_id);
ALTER TABLE sales_order_items ADD COLUMN source_quote_item_id uuid,ADD FOREIGN KEY(tenant_id,source_quote_item_id) REFERENCES service_quote_items(tenant_id,id),ADD UNIQUE(tenant_id,source_quote_item_id);
ALTER TABLE sales_order_schedules ADD COLUMN source_quote_schedule_id uuid,ADD FOREIGN KEY(tenant_id,source_quote_schedule_id) REFERENCES service_quote_schedules(tenant_id,id),ADD UNIQUE(tenant_id,source_quote_schedule_id);

CREATE FUNCTION assert_quote_order_source(tenant_key uuid,order_key uuid) RETURNS void LANGUAGE plpgsql AS $$
DECLARE h sales_orders;q service_quotes;order_number text;quote_number text;approval_hash text;acceptance_hash text;creator uuid;
BEGIN
 SELECT * INTO STRICT h FROM sales_orders WHERE tenant_id=tenant_key AND id=order_key;
 IF h.source_quote_id IS NULL THEN
  IF EXISTS(SELECT 1 FROM sales_order_items WHERE tenant_id=tenant_key AND order_id=h.id AND (source_quote_item_id IS NOT NULL OR price_snapshot ? 'sourceQuote')) OR EXISTS(SELECT 1 FROM sales_order_schedules WHERE tenant_id=tenant_key AND order_id=h.id AND source_quote_schedule_id IS NOT NULL) OR EXISTS(SELECT 1 FROM service_quotes WHERE tenant_id=tenant_key AND converted_order_id=h.id) THEN RAISE EXCEPTION 'Freier AU darf keine angenommene AG-Herkunft vortäuschen';END IF;
  RETURN;
 END IF;
 SELECT * INTO STRICT q FROM service_quotes WHERE tenant_id=tenant_key AND id=h.source_quote_id;
 SELECT number,created_by INTO STRICT order_number,creator FROM documents WHERE tenant_id=tenant_key AND id=h.id;
 SELECT number INTO STRICT quote_number FROM documents WHERE tenant_id=tenant_key AND id=q.id;
 approval_hash:=encode(sha256(convert_to(q.approved_snapshot::text,'UTF8')),'hex');acceptance_hash:=encode(sha256(convert_to(q.acceptance_snapshot::text,'UTF8')),'hex');
 IF q.status<>'ACCEPTED' OR q.converted_order_id IS DISTINCT FROM h.id OR q.converted_by IS DISTINCT FROM creator OR q.converted_at IS NULL OR q.decided_at IS NULL OR q.converted_at<q.decided_at OR h.order_date IS DISTINCT FROM (q.converted_at AT TIME ZONE 'Europe/Berlin')::date OR q.acceptance_snapshot->>'publishedHash' IS DISTINCT FROM approval_hash THEN RAISE EXCEPTION 'AU ist nicht an die tatsächliche einmalige AG-Kundenannahme gebunden';END IF;
 IF (h.organization_id,h.company_id,h.sales_area_id,h.partner_id,h.currency,h.title,h.pricing_date,h.requested_on,h.payment_term_id,h.shipping_term_id,h.incoterm_id,h.incoterm_place,h.header_text,h.internal_text,h.delivery_block,h.billing_block) IS DISTINCT FROM (q.organization_id,q.company_id,q.sales_area_id,q.partner_id,q.currency,q.title,q.pricing_date,q.requested_on,q.payment_term_id,q.shipping_term_id,q.incoterm_id,q.incoterm_place,q.header_text,q.internal_text,q.delivery_block,q.billing_block) OR h.kind<>'STANDARD' OR h.customer_reference IS DISTINCT FROM q.acceptance_snapshot->>'customerReference' OR h.customer_reference_date IS DISTINCT FROM (q.acceptance_snapshot->>'customerReferenceDate')::date THEN RAISE EXCEPTION 'AU-Kopf oder Kundenbestellung weicht vom angenommenen AG-Original ab';END IF;
 IF EXISTS((SELECT role,partner_id,address_id,contact_id,override_reason FROM sales_order_partners WHERE tenant_id=tenant_key AND order_id=h.id EXCEPT ALL SELECT role,partner_id,address_id,contact_id,override_reason FROM service_quote_partners WHERE tenant_id=tenant_key AND quote_id=q.id) UNION ALL (SELECT role,partner_id,address_id,contact_id,override_reason FROM service_quote_partners WHERE tenant_id=tenant_key AND quote_id=q.id EXCEPT ALL SELECT role,partner_id,address_id,contact_id,override_reason FROM sales_order_partners WHERE tenant_id=tenant_key AND order_id=h.id)) THEN RAISE EXCEPTION 'AU-Partnerrollen müssen genau der angenommenen AG entsprechen';END IF;
 IF (SELECT count(*) FROM sales_order_items WHERE tenant_id=tenant_key AND order_id=h.id)<>(SELECT count(*) FROM service_quote_decisions WHERE tenant_id=tenant_key AND quote_id=q.id AND decision='ACCEPT') OR NOT EXISTS(SELECT 1 FROM service_quote_decisions WHERE tenant_id=tenant_key AND quote_id=q.id AND decision='ACCEPT') THEN RAISE EXCEPTION 'AU muss genau die angenommenen AG-Positionen enthalten';END IF;
 IF EXISTS(SELECT 1 FROM sales_order_items i LEFT JOIN service_quote_items qi ON qi.tenant_id=i.tenant_id AND qi.id=i.source_quote_item_id LEFT JOIN service_quote_decisions d ON d.tenant_id=qi.tenant_id AND d.quote_id=qi.quote_id AND d.item_id=qi.id LEFT JOIN sales_order_items parent ON parent.tenant_id=i.tenant_id AND parent.id=i.parent_item_id WHERE i.tenant_id=tenant_key AND i.order_id=h.id AND (
  qi.id IS NULL OR qi.quote_id<>q.id OR d.decision IS DISTINCT FROM 'ACCEPT' OR qi.rejection_reason IS NOT NULL OR i.rejection_reason IS NOT NULL OR
  (i.position,i.product_id,i.item_category,i.customer_material,i.description,i.quantity,i.unit,i.billing_rule,i.cost_center,i.cost_object,i.profit_center,i.project_reference,i.requested_on,i.delivery_block,i.billing_block,i.item_text,i.product_snapshot,i.net,i.tax,i.gross) IS DISTINCT FROM (qi.position,qi.product_id,qi.item_category,qi.customer_material,qi.description,qi.quantity,qi.unit,qi.billing_rule,qi.cost_center,qi.cost_object,qi.profit_center,qi.project_reference,qi.requested_on,qi.delivery_block,qi.billing_block,qi.item_text,qi.product_snapshot,qi.net,qi.tax,qi.gross) OR
  parent.source_quote_item_id IS DISTINCT FROM qi.parent_item_id OR
  i.price_snapshot IS DISTINCT FROM (qi.price_snapshot || jsonb_build_object('context',qi.price_snapshot->'context'||jsonb_build_object('sourceId',h.id,'sourceNumber',order_number),'sourceQuote',jsonb_build_object('id',q.id,'number',quote_number,'itemId',qi.id,'approvalHash',approval_hash,'acceptanceHash',acceptance_hash)))
 )) THEN RAISE EXCEPTION 'AU-Position, Menge, Preis oder Hierarchie weicht von der tatsächlichen AG-Annahme ab';END IF;
 IF EXISTS((SELECT qs.id,qi.id,qs.position,qs.quantity,qs.requested_on,qs.confirmed_on FROM service_quote_schedules qs JOIN service_quote_items qi ON qi.tenant_id=qs.tenant_id AND qi.id=qs.item_id JOIN service_quote_decisions d ON d.tenant_id=qi.tenant_id AND d.item_id=qi.id AND d.quote_id=qi.quote_id AND d.decision='ACCEPT' WHERE qs.tenant_id=tenant_key AND qs.quote_id=q.id EXCEPT ALL SELECT s.source_quote_schedule_id,i.source_quote_item_id,s.position,s.quantity,s.requested_on,s.confirmed_on FROM sales_order_schedules s JOIN sales_order_items i ON i.tenant_id=s.tenant_id AND i.id=s.item_id WHERE s.tenant_id=tenant_key AND s.order_id=h.id) UNION ALL (SELECT s.source_quote_schedule_id,i.source_quote_item_id,s.position,s.quantity,s.requested_on,s.confirmed_on FROM sales_order_schedules s JOIN sales_order_items i ON i.tenant_id=s.tenant_id AND i.id=s.item_id WHERE s.tenant_id=tenant_key AND s.order_id=h.id EXCEPT ALL SELECT qs.id,qi.id,qs.position,qs.quantity,qs.requested_on,qs.confirmed_on FROM service_quote_schedules qs JOIN service_quote_items qi ON qi.tenant_id=qs.tenant_id AND qi.id=qs.item_id JOIN service_quote_decisions d ON d.tenant_id=qi.tenant_id AND d.item_id=qi.id AND d.quote_id=qi.quote_id AND d.decision='ACCEPT' WHERE qs.tenant_id=tenant_key AND qs.quote_id=q.id)) THEN RAISE EXCEPTION 'AU-Einteilungen müssen genau den angenommenen AG-Positionen entsprechen';END IF;
 IF h.status IN('IN_REVIEW','RELEASED') AND (h.approval_snapshot->'sourceQuote' IS DISTINCT FROM jsonb_build_object('id',q.id,'number',quote_number,'purpose',q.purpose,'approvalHash',approval_hash,'acceptanceHash',acceptance_hash)) THEN RAISE EXCEPTION 'AU-Prüfung muss an das tatsächliche AG-Original und die Kundenannahme gebunden sein';END IF;
 IF h.status='RELEASED' AND EXISTS(SELECT 1 FROM approval_instances ai JOIN approval_decisions ad ON ad.tenant_id=ai.tenant_id AND ad.instance_id=ai.id WHERE ai.tenant_id=tenant_key AND ai.document_id=h.id AND ai.status='APPROVED' AND ad.decision='APPROVE' AND (ad.actor_id IN(SELECT actor_id FROM service_quote_events WHERE tenant_id=tenant_key AND quote_id=q.id) OR ad.actor_id=(SELECT created_by FROM documents WHERE tenant_id=tenant_key AND id=q.id))) THEN RAISE EXCEPTION 'AG-Bearbeiter darf den übernommenen AU nicht selbst genehmigen';END IF;
END$$;

CREATE FUNCTION quote_order_header_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.source_quote_id IS DISTINCT FROM NEW.source_quote_id THEN RAISE EXCEPTION 'Angenommene AG-Herkunft des AU bleibt unveränderlich';END IF;
  IF OLD.source_quote_id IS NOT NULL AND (to_jsonb(OLD)-'status'-'version'-'approval_snapshot'-'released_snapshot'-'released_at'-'released_by'-'confirmation_number'-'cancel_reason') IS DISTINCT FROM (to_jsonb(NEW)-'status'-'version'-'approval_snapshot'-'released_snapshot'-'released_at'-'released_by'-'confirmation_number'-'cancel_reason') THEN RAISE EXCEPTION 'Angenommene AG-Konditionen des AU bleiben gebunden; eigener Änderungsprozess erforderlich';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER quote_order_header_source BEFORE INSERT OR UPDATE ON sales_orders FOR EACH ROW EXECUTE FUNCTION quote_order_header_guard();
CREATE FUNCTION quote_order_child_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE row_data jsonb;h sales_orders;q service_quotes;BEGIN
 IF TG_OP='UPDATE' AND (OLD.tenant_id,OLD.order_id) IS DISTINCT FROM (NEW.tenant_id,NEW.order_id) THEN RAISE EXCEPTION 'AU-Partner, Positionen und Einteilungen behalten ihren tatsächlichen Auftragsursprung';END IF;
 row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 SELECT * INTO STRICT h FROM sales_orders WHERE tenant_id=(row_data->>'tenant_id')::uuid AND id=(row_data->>'order_id')::uuid;
 IF h.source_quote_id IS NULL THEN
  IF row_data->>'source_quote_item_id' IS NOT NULL OR row_data->>'source_quote_schedule_id' IS NOT NULL THEN RAISE EXCEPTION 'Freier AU darf keine angenommenen AG-Positionen zuordnen';END IF;
 ELSE
  SELECT * INTO STRICT q FROM service_quotes WHERE tenant_id=h.tenant_id AND id=h.source_quote_id FOR SHARE;
  IF TG_OP<>'INSERT' OR q.converted_order_id IS NOT NULL OR q.status<>'ACCEPTED' OR h.status<>'DRAFT' THEN RAISE EXCEPTION 'Angenommene AG-Positionen, Partner und Einteilungen bleiben im AU gebunden';END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END$$;
CREATE TRIGGER quote_order_partner_source BEFORE INSERT OR UPDATE OR DELETE ON sales_order_partners FOR EACH ROW EXECUTE FUNCTION quote_order_child_guard();
CREATE TRIGGER quote_order_item_source BEFORE INSERT OR UPDATE OR DELETE ON sales_order_items FOR EACH ROW EXECUTE FUNCTION quote_order_child_guard();
CREATE TRIGGER quote_order_schedule_source BEFORE INSERT OR UPDATE OR DELETE ON sales_order_schedules FOR EACH ROW EXECUTE FUNCTION quote_order_child_guard();
CREATE FUNCTION quote_order_consistent() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE row_data jsonb;order_key uuid;BEGIN
 row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;order_key:=CASE WHEN TG_TABLE_NAME='sales_orders' THEN (row_data->>'id')::uuid ELSE (row_data->>'order_id')::uuid END;
 PERFORM assert_quote_order_source((row_data->>'tenant_id')::uuid,order_key);RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER quote_order_complete AFTER INSERT OR UPDATE ON sales_orders DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION quote_order_consistent();
CREATE CONSTRAINT TRIGGER quote_order_partner_complete AFTER INSERT OR UPDATE OR DELETE ON sales_order_partners DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION quote_order_consistent();
CREATE CONSTRAINT TRIGGER quote_order_item_complete AFTER INSERT OR UPDATE OR DELETE ON sales_order_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION quote_order_consistent();
CREATE CONSTRAINT TRIGGER quote_order_schedule_complete AFTER INSERT OR UPDATE OR DELETE ON sales_order_schedules DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION quote_order_consistent();

CREATE FUNCTION quote_sales_execution_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF NEW.source_sales_order_id IS NOT NULL AND EXISTS(SELECT 1 FROM sales_orders h JOIN service_quotes q ON q.tenant_id=h.tenant_id AND q.id=h.source_quote_id WHERE h.tenant_id=NEW.tenant_id AND h.id=NEW.source_sales_order_id AND q.purpose='SALES_QUOTATION') THEN RAISE EXCEPTION 'Verkaufsangebot führt in Direktvertrieb, nicht in künstlichen Serviceauftrag';END IF;RETURN NEW;
END$$;
CREATE TRIGGER quote_sales_execution_source BEFORE INSERT OR UPDATE ON service_orders FOR EACH ROW EXECUTE FUNCTION quote_sales_execution_guard();
